SELECT MAX(attempt_no)
FROM quiz_attempts
WHERE user_id = #{userId}
  AND quiz_type = 'SUB_CHAPTER'
  AND sub_chapter_id = #{subChapterId}

SELECT MAX(attempt_no)
FROM quiz_attempts
WHERE user_id = #{userId}
  AND quiz_type = 'MAIN_CHAPTER'
  AND main_chapter_id = #{mainChapterId}

